const adds = $('Get Trending Adds')
  .all()
  .map((item) => item.json)
  .filter((item) => item && item.player_id);

const drops = $('Get Trending Drops')
  .all()
  .map((item) => item.json)
  .filter((item) => item && item.player_id);

const playerMap = $('Get Active Player Map').first().json ?? {};

const safe = (value, fallback = 'Unknown') => {
  if (value === null || value === undefined || value === '') return fallback;
  return String(value)
    .replaceAll('@', '@\u200b')
    .replaceAll('`', 'ˋ')
    .replaceAll('*', '∗')
    .replaceAll('_', '﹍');
};

const playerLabel = (playerId) => {
  const player = playerMap[playerId] ?? {};
  const fullName =
    player.full_name ||
    [player.first_name, player.last_name].filter(Boolean).join(' ') ||
    playerId;

  const details = [player.position, player.team].filter(Boolean).join(' · ');
  const injury = player.injury_status ? ` · ${player.injury_status}` : '';

  return {
    name: safe(fullName, playerId),
    details: details ? ` (${safe(details)}${safe(injury, '')})` : '',
  };
};

const makeLines = (records, symbol) => {
  if (!records.length) return '_No trending players returned for this period._';

  return records
    .slice(0, 10)
    .map((record, index) => {
      const player = playerLabel(String(record.player_id));
      return `${index + 1}. ${symbol} **${player.name}**${player.details} — ${Number(record.count ?? 0).toLocaleString('en-US')}`;
    })
    .join('\n');
};

const generatedAt = new Date().toISOString();

return [
  {
    json: {
      content:
        '🏈 **Sleeper Fantasy Football Trending Digest**\n' +
        'Top adds and drops over the last 24 hours. Trending data provided by Sleeper.',
      addsDescription: makeLines(adds, '➕'),
      dropsDescription: makeLines(drops, '➖'),
      generatedAt,
      summary: {
        addsReturned: adds.length,
        dropsReturned: drops.length,
        playerRecordsAvailable: Object.keys(playerMap).length,
      },
    },
  },
];
